#include <stdint.h>
#include "cpp_link_probe.h"
#include "class_behavior_probe.h"
#include "engine_control_v2_probe.h"
#include "uart_echo_probe.h"
#include "vehicle_runtime.h"
#include "gpio_diagnostics.h"

/* Inspect this value in the debugger after the C++ call: expected 42. */
volatile uint32_t vvvp_cpp_probe_result = 0U;

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
    vvvp_cpp_probe_result = vvvp_cpp_link_probe();
    vvvp_run_class_behavior_probe();
    vvvp_run_engine_control_v2_probe();
    vvvp_vehicle_input_init();

    /* Keep the existing verification independent of UART availability. */
    vvvp_uart_echo_init();
    vvvp_gpio_diag_init();
    vvvp_vehicle_control_init();

    for (;;)
    {
        vvvp_uart_echo_poll();
        vvvp_vehicle_control_poll();
        vvvp_vehicle_input_poll();
    }
}
